"""PPOIS6: lifecycle, computed calendar and three officially sourced analogs."""
from pathlib import Path
import json

from report_layout import Report, SUBJECT


def build():
    plan = json.loads((SUBJECT/'Планирование/План_разработки.json').read_text(encoding='utf-8'))
    r = Report(6, 'Этапы разработки и обзор существующих информационных систем')
    r.heading('Этапы разработки и обзор существующих информационных систем')
    r.heading('Цель и задание', 2)
    r.paragraph('Цель работы — спланировать разработку информационной системы формирования и актуализации карточек компьютерных систем ООО «Юкомс» и сравнить существующие решения. Требуется сформировать этапы жизненного цикла, построить календарный график и рассмотреть не менее трёх информационных систем.')
    r.paragraph('Проект продолжает практики 1–5: система связывает состав компьютерной конфигурации, предложения поставщиков, проверку совместимости, расчёт цены и массы и ревизию карточки. Для выбранного учебного плана требуется 70 человеко-дней; календарная продолжительность составляет 37 рабочих дней. Оценки относятся к планируемой разработке, а не к фактически затраченному времени.')
    r.heading('1 Этапы жизненного цикла')
    r.paragraph('Применяется итерационный подход: сначала уточняются требования и архитектура, затем проверяется вертикальный срез от состава конфигурации до подготовленной карточки. После него добавляются интеграция и обработка внешних результатов. Пилот не подменяет промышленное внедрение: выход в эксплуатацию требует согласования данных поставщиков и внешнего обмена.')
    r.page(True)
    r.heading('1.1 Исполнители и трудоёмкость', 2)
    rows=[]
    for t in plan['tasks']:
        rows.append([t['id'], t['name'], '\n'.join(t['effort']),
                     '\n'.join(str(effort) for effort in t['effort'].values()),t['duration']])
    r.table('Этапы разработки информационной системы',
            ['№','Название этапа','Исполнитель','Трудоёмкость, чел/дни','Продолжительность работ, дни'],
            rows,[.7,5.3,7,3.8,3.5],center=(0,3,4),lead='Этапы и оценки представлены в таблице 1. Значения трудоёмкости по строкам соответствуют исполнителям слева; продолжительность указана в рабочих днях.')
    r.page(True,new_page=True)
    r.heading('2 Календарный график')
    r.figure('Календарный план: этапы, задачи и исполнители',SUBJECT/'Схемы/01_ПР6_Гант_этапы_задачи.png',max_height=14,
             lead='На рисунке 1 показаны сводные этапы и вложенные задачи с исполнителями. Сводные полосы охватывают сроки этапов; отдельные рабочие дни задач показаны прямоугольниками.')
    r.page(False)
    r.paragraph('План начинается 5 октября и завершается 25 ноября 2026 года. Принята пятидневная неделя: суббота, воскресенье и 4 ноября исключены. Восемь этапов разделены на 16 задач; этап 5 выполняется параллельно этапам 3 и 4. Назначения задач в сумме дают трудоёмкость соответствующего этапа.')
    r.paragraph('В графике Backend и Frontend обозначают разработчиков серверной и клиентской частей, Рук. проекта — руководителя проекта, Адм. БД — администратора базы данных, Эксплуатация — инженера эксплуатации. Полные наименования исполнителей приведены в таблице 1.')
    r.paragraph('Критический путь проходит через этапы 1–2–3–4–6–7–8 и занимает 37 рабочих дней. Клиентские формы — обязательный этап 5: проектирование выполняется 19–21 октября, реализация — 22–27 октября. Интеграция начинается 9 ноября после завершения доменной логики и клиентских форм.')
    r.paragraph('Между завершением форм и началом интеграции имеется запас в семь рабочих дней. Это допустимый сдвиг окончания этапа 5 без изменения срока проекта; его трудоёмкость и состав задач сохраняются. Один человеко-день соответствует восьми часам работы. Для каждой роли принят отдельный исполнитель; назначения проверены на отсутствие перегрузки.')
    r.heading('3 Обзор существующих решений')
    r.paragraph('Для сравнения выбраны МойСклад, 1С:Управление нашей фирмой и 1С-Битрикс:Управление сайтом. Они покрывают разные части задачи: товарный и складской учёт, производство и ценообразование, веб-каталог и продажу комплектов. Сведения о функциях и ценах проверены по официальным страницам 5 октября 2026 года [2–7].')
    r.page(True)
    r.heading('3.1 Сравнение информационных систем',2)
    r.table('Существующие информационные системы',
        ['Информационная\nсистема','Функционал','Стоимость, руб.','Необходимое оборудование','Характеристики'],[
        ['МойСклад, тариф Проф','Каталог, склад, закупки, продажи, цены; права пользователей и интеграции [2, 3].',
         '4 100 в месяц; 3 280 в месяц при оплате за год. Опции оплачиваются отдельно [2].',
         'Рабочие ПК с браузером и интернетом; сервер SaaS у поставщика. Собственный сервер в выбранной схеме не требуется.',
         'Облачная подписка. Подходит для централизованного учёта; доменную проверку компьютерной конфигурации следует оценивать отдельным прототипом.'],
        ['1С:Управление нашей фирмой, пакет на 5 мест','Закупки, склад, производственный учёт, затраты, цены и планирование ресурсов [4].',
         '55 900 за пакет на 5 рабочих мест. Настройка и обслуживание по 1С:ИТС — отдельно [5].',
         'Пять рабочих ПК и выделенный узел для общей информационной базы — допущение локальной схемы, не минимум производителя.',
         'Локальный пакет. Сильная учётная часть; доменные правила и единый снимок карточки требуют согласованного расширения.'],
        ['1С-Битрикс:Управление сайтом, Бизнес','Веб-каталог, разные типы цен, несколько складов, наборы и комплекты [6].',
         '96 500 за лицензию. Хостинг, настройка и сторонние модули — отдельно [7].',
         'Рабочие ПК с браузером; веб-хостинг или сервер приложения с БД. Мощность определяется нагрузочным тестированием.',
         'CMS интернет-магазина. Комплект товаров не равнозначен инженерной проверке совместимости комплектующих.'],
        ],[4.3,5.5,4.2,5.7,5.5],lead='Функции, опубликованная стоимость и принятая схема размещения сравниваются в таблице 2. Оборудование описывает варианты развёртывания, а не подтверждённые минимальные требования производителей.')
    r.page(False)
    r.heading('3.2 Стоимость и пригодность для проекта',2)
    r.paragraph('Подписку SaaS и разовую лицензию нельзя сравнивать как одинаковые платежи. Базовый год тарифа Проф стоит 39 360 руб. при единовременной оплате за год или 49 200 руб. при помесячной оплате. Дополнительные опции, внедрение и обмен данными в эти суммы не входят. Для 1С:УНФ и Битрикс приведён только стартовый лицензионный платёж; стоимость сопровождения и инфраструктуры требует отдельной сметы.')
    r.paragraph('МойСклад подходит как источник товарного учёта и остатков, 1С:УНФ — как учётная основа сборки и закупок, Битрикс — как платформа витрины. Из приведённых публичных описаний нельзя подтвердить полное покрытие проверки сокета, типа памяти, мощности питания, фиксации выбранного предложения и обработки UNKNOWN при публикации. Это вывод о необходимости проверки доменных требований, а не утверждение об отсутствии любой возможной доработки продуктов.')
    r.paragraph('Для учебного проекта выбирается отдельный доменный модуль поверх нормализованной БД. Он позволяет проверить ключевую цепочку «состав — предложение — совместимость — расчёт — ревизия карточки» и затем подключить выбранную учётную систему. Использование готового продукта может сократить учётную часть, но не отменяет проверки согласованности версии и внешнего результата.')
    r.heading('Вывод')
    r.paragraph('Сформирован план из восьми этапов с трудоёмкостью 70 человеко-дней и продолжительностью 37 рабочих дней. Проверены зависимости, критический путь и загрузка исполнителей. Обзор трёх решений показал, какие учётные и торговые функции можно использовать готовыми и какие доменные требования нужно проверять отдельно. Итоговый выбор промышленного решения зависит от бюджета внедрения, условий интеграции и результатов пилота.')
    r.sources([
        'Практическая работа №6. Этапы разработки ИС. Обзор существующих разработок. Методические материалы ППОИС, предоставленные к заданию, 1 с.',
        'МойСклад. Тарифы. https://www.moysklad.ru/subscription/ (дата обращения: 05.10.2026).',
        'МойСклад. Возможности. https://www.moysklad.ru/vozmozhnosti/ (дата обращения: 05.10.2026).',
        '1С. Возможности 1С:Управление нашей фирмой. https://v8.1c.ru/small.biz/vozmozhnosti-1sunf/ (дата обращения: 05.10.2026).',
        '1С. Цена 1С:Управление нашей фирмой. https://v8.1c.ru/small.biz/cena-1s-upravlenie-nashey-firmoy/ (дата обращения: 05.10.2026).',
        '1С-Битрикс. Преимущества редакции Бизнес. https://www.1c-bitrix.ru/products/cms/business/index_m.php (дата обращения: 05.10.2026).',
        '1С-Битрикс. Купить Управление сайтом. https://www.1c-bitrix.ru/buy/products/cms.php (дата обращения: 05.10.2026).',
    ])
    return r.save()


if __name__=='__main__':
    build()
